// Content with portions generated by generative AI platform
package org.eclipse.kura.linux.watchdog;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertThrows;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

import org.eclipse.kura.KuraException;
import org.junit.Test;

public class SystemdWatchdogBackendTest {

    private static final String NOTIFY_SOCKET = "/tmp/test-notify-socket";

    private TestSystemdBackend backend;
    private boolean activated;

    @Test
    public void activationFailsWithoutNotifySocket() {
        givenBackend(null, true, null);

        thenActivationFails();
    }

    @Test
    public void activationFailsWhenNotifyBinaryIsMissing() {
        givenBackend(NOTIFY_SOCKET, false, null);

        thenActivationFails();
    }

    @Test
    public void watchdogUsecFromEnvironmentIsUsed() throws Exception {
        givenBackend(NOTIFY_SOCKET, true, "30000000");

        whenBackendIsConfigured();

        thenBackendIsActive();
        thenWatchdogUsecIs(30000000L);
        thenHardwareTimeoutIs(30000);
    }

    @Test
    public void watchdogUsecIsNotSentWhenSetByEnvironment() throws Exception {
        givenBackend(NOTIFY_SOCKET, true, "30000000");

        whenBackendIsConfigured();
        whenBackendIsTicked();
        whenBackendIsStopped();

        thenMessagesSentAre("WATCHDOG=1");
    }

    @Test
    public void watchdogUsecIsSentWhenNotSetByEnvironment() throws Exception {
        givenBackend(NOTIFY_SOCKET, true, null);

        whenBackendIsConfigured();
        whenBackendIsTicked();
        whenBackendIsStopped();

        thenMessagesSentAre("WATCHDOG_USEC=20000000", "WATCHDOG=1", "WATCHDOG_USEC=0");
        thenHardwareTimeoutIs(20000);
    }

    @Test
    public void invalidWatchdogUsecFromEnvironmentIsIgnored() throws Exception {
        givenBackend(NOTIFY_SOCKET, true, "abc");

        whenBackendIsConfigured();

        thenBackendIsActive();
        thenMessagesSentAre("WATCHDOG_USEC=20000000");
    }

    @Test
    public void backendIsNotActiveWhenAnotherModeIsSelected() throws Exception {
        givenBackend(NOTIFY_SOCKET, true, "30000000");

        whenBackendIsConfiguredForMode("direct");

        thenBackendIsNotActive();
    }

    private void givenBackend(String notifySocket, boolean notifyAvailable, String watchdogUsec) {
        this.backend = new TestSystemdBackend(notifySocket, notifyAvailable, watchdogUsec);
    }

    private void whenBackendIsConfigured() throws Exception {
        whenBackendIsConfiguredForMode("systemd");
    }

    private void whenBackendIsConfiguredForMode(String mode) throws Exception {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", true);
        properties.put("watchdogMode", mode);
        this.activated = this.backend.configure(new WatchdogServiceOptions(properties), Optional.empty());
    }

    private void whenBackendIsTicked() throws Exception {
        this.backend.onTick(Optional.empty());
    }

    private void whenBackendIsStopped() {
        this.backend.stop(false);
    }

    private void thenActivationFails() {
        assertThrows(KuraException.class, this::whenBackendIsConfigured);
    }

    private void thenBackendIsActive() {
        assertTrue(this.activated);
    }

    private void thenBackendIsNotActive() {
        assertFalse(this.activated);
    }

    private void thenWatchdogUsecIs(long expectedUsec) {
        assertEquals(expectedUsec, this.backend.getWatchdogUsec());
    }

    private void thenHardwareTimeoutIs(int expectedTimeoutMs) {
        assertEquals(expectedTimeoutMs, this.backend.getHardwareTimeout());
    }

    private void thenMessagesSentAre(String... expectedMessages) {
        assertEquals(Arrays.asList(expectedMessages), this.backend.sentMessages);
    }

    private static class TestSystemdBackend extends SystemdWatchdogBackend {

        private final String notifySocket;
        private final boolean notifyAvailable;
        private final String watchdogUsec;
        private final List<String> sentMessages = new ArrayList<>();

        TestSystemdBackend(String notifySocket, boolean notifyAvailable, String watchdogUsec) {
            this.notifySocket = notifySocket;
            this.notifyAvailable = notifyAvailable;
            this.watchdogUsec = watchdogUsec;
        }

        @Override
        protected synchronized boolean sendNotify(String message) {
            this.sentMessages.add(message);
            return true;
        }

        @Override
        protected Optional<String> getEnvVar(String name) {
            if (NOTIFY_SOCKET_ENV.equals(name)) {
                return Optional.ofNullable(this.notifySocket);
            }
            if (WATCHDOG_USEC_ENV.equals(name)) {
                return Optional.ofNullable(this.watchdogUsec);
            }
            return Optional.empty();
        }

        @Override
        protected boolean isSystemdNotifyAvailable() {
            return this.notifyAvailable;
        }
    }
}
